  return s;
}

const norm = (t) => String(t || '').replace(/\s+/g, ' ').trim();

function validate(state, content) {
  const out = { status: 'ok', problems: [] };
  let d = null;
  const raw = String(content || '').trim().replace(/^```(json)?\s*/, '').replace(/```$/, '');
  try { d = JSON.parse(raw); } catch (e) { out.problems.push('answer is not JSON'); }
  const isStr = (v) => typeof v === 'string' && v.length > 0;
  if (d) {
    if (!isStr(d.summary)) out.problems.push('summary missing');
    if (!d.root_cause || !isStr(d.root_cause.statement)) out.problems.push('root_cause.statement missing');
    if (!d.root_cause || !CONFIDENCE.includes(d.root_cause.confidence)) out.problems.push('root_cause.confidence invalid');
    if (!Array.isArray(d.evidence)) out.problems.push('evidence is not a list');
    if (!d.fix || !Array.isArray(d.fix.steps)) out.problems.push('fix.steps is not a list');
  }
  if (!d || out.problems.length) {
    const status = state.end_reason === 'answered' ? 'invalid' : state.end_reason === 'error' ? 'error' : 'inconclusive';
    const summary = { invalid: 'Diagnosis output failed validation', error: `Diagnosis failed: ${raw.slice(0, 200)}`,
      inconclusive: `Inconclusive: ${state.end_reason}` }[status];
    return { status, diagnosis: {
      summary,
      root_cause: { statement: '', confidence: 'unknown', capability: '' }, evidence: [], ruled_out: [], unexplained_alerts: [],
      fix: { where: '', steps: [], is_manifest_change: false }, verify_after_fix: '',
      validation: out.problems, raw: raw.slice(0, 2000), tokens: { in: state.tokens_in, out: state.tokens_out },
      tool_calls: state.log.map((l) => ({ call_id: l.call_id, tool: l.tool, args: JSON.stringify(l.args), ok: l.ok })) } };
  }
  const byId = new Map(state.log.filter((l) => l.ok).map((l) => [l.call_id, l]));
  d.evidence = d.evidence.slice(0, 20).map((e) => {
    const call = byId.get(e && e.call_id);
    const quoted = call && norm(e.excerpt).length >= 3 && norm(call.text).includes(norm(e.excerpt));
    const ev = { call_id: String((e && e.call_id) || ''), tool: call ? call.tool : String((e && e.tool) || ''),
      args: call ? JSON.stringify(call.args) : String((e && e.args) || ''), excerpt: String((e && e.excerpt) || '').slice(0, 600),
      kind: quoted ? 'observed' : 'inferred' };
    if (!quoted && e && e.kind === 'observed') {
      ev.note = call ? 'downgraded: excerpt not found in that call\'s result' : 'downgraded: no tool call with that id ran';
    }
    return ev;
  });
  const observed = d.evidence.filter((e) => e.kind === 'observed').length;
  let status = 'ok';
  if (state.end_reason !== 'answered') {
    status = 'inconclusive';
    d.root_cause.confidence = 'unknown';
    d.summary = `Inconclusive (${state.end_reason}): ${d.summary}`;
  } else if (d.root_cause.confidence === 'confirmed' && observed === 0) {
    d.root_cause.confidence = 'likely';
    d.root_cause.note = 'downgraded from confirmed: no evidence item quotes a tool result';
  }
  d.tokens = { in: state.tokens_in, out: state.tokens_out };
  d.tool_calls = state.log.map((l) => ({ call_id: l.call_id, tool: l.tool, args: JSON.stringify(l.args), ok: l.ok }));
  return { status, diagnosis: d };
}


