const state = $('Next Turn').first().json.state;
const r = step(state, $input.first().json, DateTime.now().toUTC().toISO(), $('Settings').first().json);
// The request body is built here: n8n expressions refuse to read a property named `arguments`.
if (r.kind === 'tools') {
  return r.calls.map((call) => ({ json: { kind: 'tools', call, state: r.state,
    body: JSON.stringify({ server_id: call.mcp.server_id, name: call.mcp.name, arguments: call.mcp.arguments }) } }));
}
return [{ json: r }];

// Health diagnosis: an LLM investigates one issue through read-only tools under hard budgets that
// this code enforces. The LLM never decides whether something is wrong or who is told; it explains
