    if (!d.root_cause || !CONFIDENCE.includes(d.root_cause.confidence)) out.problems.push('root_cause.confidence invalid');
    if (!Array.isArray(d.evidence)) out.problems.push('evidence is not a list');
    if (!d.fix || !Array.isArray(d.fix.steps)) out.problems.push('fix.steps is not a list');
