      validation: out.problems, raw: raw.slice(0, 2000), tokens: { in: state.tokens_in, out: state.tokens_out },
      tool_calls: state.log.map((l) => ({ call_id: l.call_id, tool: l.tool, args: JSON.stringify(l.args), ok: l.ok })) } };
  }
  const byId = new Map(state.log.filter((l) => l.ok).map((l) => [l.call_id, l]));
  d.evidence = d.evidence.slice(0, 20).map((e) => {
    const call = byId.get(e && e.call_id);
    const quoted = call && norm(e.excerpt).length >= 3 && norm(call.text).includes(norm(e.excerpt));
    const ev = { call_id: String((e && e.call_id) || ''), tool: call ? call.tool : String((e && e.tool) || ''),
