// Health diagnosis: an LLM investigates one issue through read-only tools under hard budgets that
// this code enforces. The LLM never decides whether something is wrong or who is told; it explains
// why, and every claim it makes is checked against the tool calls that actually ran.

const DIAGNOSIS_LIMITS = {
  max_tool_calls: 8, max_input_tokens: 120000, max_seconds: 300, max_result_chars: 16000,
  max_turns: 12, max_loki_minutes: 720, max_range_minutes: 360, max_log_lines: 200,
};
const CONFIDENCE = ['confirmed', 'likely', 'unknown'];

const TOOLS = [
  ['prometheus_query', 'Instant PromQL query against the homelab Prometheus (both clusters; nas series carry k8s_cluster="nas").',
    { query: { type: 'string' } }, ['query']],
  ['prometheus_range', 'Range PromQL query. minutes <= 360.',
    { query: { type: 'string' }, minutes: { type: 'integer' }, step_seconds: { type: 'integer' } }, ['query', 'minutes']],
  ['loki_query', 'LogQL query over the last `minutes` (<= 720), at most `limit` (<= 100) lines. The stream selector must pin namespace, host, pod, app, job, systemd_unit or syslog_identifier with an exact match.',
    { query: { type: 'string' }, minutes: { type: 'integer' }, limit: { type: 'integer' } }, ['query', 'minutes']],
  ['k8s_get', 'Get one Kubernetes object.',
    { cluster: { type: 'string', enum: ['homelab', 'nas'] }, apiVersion: { type: 'string' }, kind: { type: 'string' }, namespace: { type: 'string' }, name: { type: 'string' } },
    ['cluster', 'apiVersion', 'kind', 'name']],
  ['k8s_list', 'List Kubernetes objects. Requires a namespace (except for cluster-scoped kinds) and a labelSelector or fieldSelector.',
    { cluster: { type: 'string', enum: ['homelab', 'nas'] }, apiVersion: { type: 'string' }, kind: { type: 'string' }, namespace: { type: 'string' }, labelSelector: { type: 'string' }, fieldSelector: { type: 'string' } },
    ['cluster', 'apiVersion', 'kind']],
  ['k8s_events', 'Kubernetes events in one namespace.',
    { cluster: { type: 'string', enum: ['homelab', 'nas'] }, namespace: { type: 'string' } }, ['cluster', 'namespace']],
  ['pod_logs', 'Last lines (tail <= 200) of one container of one pod.',
    { cluster: { type: 'string', enum: ['homelab', 'nas'] }, namespace: { type: 'string' }, name: { type: 'string' }, container: { type: 'string' }, tail: { type: 'integer' } },
    ['cluster', 'namespace', 'name']],
].map(([name, description, properties, required]) => ({
  type: 'function', function: { name, description, parameters: { type: 'object', properties, required, additionalProperties: false } },
}));

const CLUSTER_SCOPED = new Set(['Node', 'Namespace', 'PersistentVolume', 'StorageClass', 'ClusterRole', 'ClusterRoleBinding',
  'CustomResourceDefinition', 'IngressClass', 'PriorityClass']);
const SELECTIVE_LABELS = /(namespace|host|pod|app|job|systemd_unit|syslog_identifier|container)\s*=\s*"[^"*]+"/;

// Maps a model-facing call to an MCP call through LiteLLM, or refuses it with a reason the model sees.
function toMcp(name, a, cfg, nowIso) {
  const minutesAgo = (m) => DateTime.fromISO(nowIso).minus({ minutes: m }).toUTC().toISO();
  const clamp = (v, lo, hi, d) => Math.max(lo, Math.min(hi, Number.isFinite(Number(v)) ? Number(v) : d));
  const k8s = (cluster) => (cluster === 'nas' ? 'kubernetes_nas_mcp' : cluster === 'homelab' ? 'kubernetes_homelab_mcp' : null);
  switch (name) {
    case 'prometheus_query':
      if (!a.query) return { refused: 'query is required' };
      return { server_id: 'grafana_mcp', name: 'query_prometheus', arguments: { datasourceUid: cfg.prometheus_uid, expr: a.query, queryType: 'instant', endTime: 'now' } };
    case 'prometheus_range': {
      if (!a.query) return { refused: 'query is required' };
      const minutes = clamp(a.minutes, 1, DIAGNOSIS_LIMITS.max_range_minutes, 60);
      return { server_id: 'grafana_mcp', name: 'query_prometheus', arguments: { datasourceUid: cfg.prometheus_uid, expr: a.query, queryType: 'range',
        startTime: `now-${minutes}m`, endTime: 'now', stepSeconds: clamp(a.step_seconds, 30, 3600, Math.max(60, minutes)) } };
    }
    case 'loki_query': {
      const selector = String(a.query || '').split('}')[0];
      if (!SELECTIVE_LABELS.test(selector)) return { refused: 'the stream selector must pin namespace, host, pod, app, job, container, systemd_unit or syslog_identifier with an exact match' };
      return { server_id: 'grafana_mcp', name: 'query_loki_logs', arguments: { datasourceUid: cfg.loki_uid, logql: a.query,
        startRfc3339: minutesAgo(clamp(a.minutes, 1, DIAGNOSIS_LIMITS.max_loki_minutes, 60)), limit: clamp(a.limit, 1, 100, 50) } };
    }
    case 'k8s_get':
      if (!k8s(a.cluster)) return { refused: 'cluster must be homelab or nas' };
      return { server_id: k8s(a.cluster), name: 'resources_get', arguments: { apiVersion: a.apiVersion, kind: a.kind, name: a.name, ...(a.namespace ? { namespace: a.namespace } : {}) } };
    case 'k8s_list': {
      if (!k8s(a.cluster)) return { refused: 'cluster must be homelab or nas' };
      if (!a.namespace && !CLUSTER_SCOPED.has(a.kind)) return { refused: 'a namespace is required' };
      if (!a.labelSelector && !a.fieldSelector) return { refused: 'a labelSelector or fieldSelector is required; unbounded lists are not allowed' };
      const args = { apiVersion: a.apiVersion, kind: a.kind };
      for (const k of ['namespace', 'labelSelector', 'fieldSelector']) if (a[k]) args[k] = a[k];
      return { server_id: k8s(a.cluster), name: 'resources_list', arguments: args };
    }
    case 'k8s_events':
      if (!k8s(a.cluster)) return { refused: 'cluster must be homelab or nas' };
      if (!a.namespace) return { refused: 'a namespace is required' };
      return { server_id: k8s(a.cluster), name: 'events_list', arguments: { namespace: a.namespace } };
    case 'pod_logs':
      if (!k8s(a.cluster)) return { refused: 'cluster must be homelab or nas' };
      return { server_id: k8s(a.cluster), name: 'pods_log', arguments: { namespace: a.namespace, name: a.name,
        tail: clamp(a.tail, 1, DIAGNOSIS_LIMITS.max_log_lines, 100), ...(a.container ? { container: a.container } : {}) } };
    default:
      return { refused: `unknown tool ${name}` };
  }
}

const OUTPUT_SHAPE = `{"summary": "one line",
 "impact": {"capabilities": ["..."], "blast_radius": "..."},
 "root_cause": {"statement": "...", "confidence": "confirmed|likely|unknown", "capability": "..."},
 "evidence": [{"call_id": "<id of the tool call>", "tool": "<tool name>", "args": "...", "excerpt": "<text copied exactly from that call's result>", "kind": "observed|inferred"}],
 "ruled_out": [{"hypothesis": "...", "refuted_by": "..."}],
 "unexplained_alerts": ["..."],
 "fix": {"where": "repository and path, or the object to change", "steps": ["..."], "is_manifest_change": true},
 "verify_after_fix": "..."}`;

function prepare({ cfg, issue, issues, events, playbooks, nowIso, maxToolCalls }) {
  const open = issues.filter((r) => r.status === 'open' && r.fingerprint !== issue.fingerprint);
  const attached = open.filter((r) => r.root_cause_fp === issue.fingerprint);
  const sameArea = open.filter((r) => r.cluster === issue.cluster && r.root_cause_fp !== issue.fingerprint
    && (r.capability === issue.capability || (issue.subject && r.subject === issue.subject))).slice(0, 15);
  const upstream = Object.entries(cfg.dependencies || {}).filter(([, downs]) => downs.includes(issue.capability)).map(([u]) => u);
  const upstreamStatus = upstream.map((u) => `${u}: ${open.some((r) => r.cluster === issue.cluster && r.capability === u) ? 'FIRING' : 'not firing'}`);
  const brief = (r) => ({ tier: r.tier, alertname: r.alertname, title: r.title, subject: r.subject, severity: r.severity,
    first_seen: r.first_seen, labels: JSON.parse(r.labels_json || '{}'), annotations: JSON.parse(r.annotations_json || '{}') });
  const pack = {
    issue: { ...brief(issue), capability: issue.capability, cluster: issue.cluster, status: issue.status, recurrences: issue.recurrences },
    attached_downstream_issues: attached.map(brief),
    other_open_issues_same_area: sameArea.map(brief),
    upstream_capabilities: upstreamStatus,
    history: events.slice(-20).map((e) => `${e.ts} ${e.transition} ${e.detail}`),
  };
  const playbook = playbooks[issue.capability] || playbooks.default;
  const system = [
    'You diagnose one problem in a two-cluster Kubernetes homelab (clusters homelab and nas). You have read-only tools.',
    'The alerting system has already decided this problem is real. Your job is only to find why, and how to fix it.',
    `Budget: at most ${maxToolCalls} tool calls. Results longer than about 4k tokens are cut. Lists need a namespace and a selector.`,
    'Method: 1) state 1 to 4 hypotheses, each with what it predicts and the single most discriminating tool call;',
    '2) run the most discriminating call first and update; 3) before calling anything "confirmed", run two checks as tool calls:',
    'something the hypothesis must leave behind is present, and something that would be seen if it were false is absent.',
    'Stop at a confirmed hypothesis, when the cause is in another capability, or when two calls in a row add nothing.',
    'Evidence: cite the call_id of the tool call and copy the excerpt exactly from its result. Anything not from a tool result is kind "inferred".',
    `Answer with JSON only, no prose and no code fence, in this shape:\n${OUTPUT_SHAPE}`,
    `Playbook for ${issue.capability || 'this alert'}:\n${playbook}`,
  ].join('\n');
  return {
    model: cfg.model, fallbacks: cfg.fallbacks,
    messages: [{ role: 'system', content: system }, { role: 'user', content: `Evidence pack:\n${JSON.stringify(pack, null, 1)}` }],
    calls: 0, max_tool_calls: maxToolCalls, tokens_in: 0, tokens_out: 0, turns: 0, started: nowIso,
    log: [], final_turn: false, end_reason: '',
  };
}

function step(state, resp, nowIso, cfg) {
  const s = JSON.parse(JSON.stringify(state));
  const done = (reason, content) => ({ kind: 'done', state: { ...s, end_reason: reason }, content: content || '' });
  if (!resp || resp.error || !Array.isArray(resp.choices)) {
    return done('error', `model call failed: ${JSON.stringify((resp && resp.error) || resp).slice(0, 300)}`);
  }
  s.turns += 1;
  s.tokens_in += (resp.usage && resp.usage.prompt_tokens) || 0;
  s.tokens_out += (resp.usage && resp.usage.completion_tokens) || 0;
  const msg = resp.choices[0].message || {};
  const calls = Array.isArray(msg.tool_calls) ? msg.tool_calls : [];
  if (!calls.length) return done(s.final_turn ? s.end_reason || 'budget' : 'answered', msg.content || '');
  s.messages.push({ role: 'assistant', content: msg.content || null, tool_calls: calls });
  if (s.tokens_in > DIAGNOSIS_LIMITS.max_input_tokens) return done('token budget');
  if (DateTime.fromISO(nowIso).diff(DateTime.fromISO(s.started), 'seconds').seconds > DIAGNOSIS_LIMITS.max_seconds) return done('time budget');
  if (s.turns >= DIAGNOSIS_LIMITS.max_turns || s.final_turn) return done(s.end_reason || 'turn budget');
  const run = [];
  for (const c of calls) {
    let args = {};
    try { args = JSON.parse(c.function.arguments || '{}'); } catch (e) { args = null; }
    let reply = null;
    if (args === null) reply = 'refused: arguments are not valid JSON';
    else if (s.calls >= s.max_tool_calls) { reply = 'refused: tool call budget exhausted'; s.end_reason = 'tool call budget'; }
    else {
      const mcp = toMcp(c.function.name, args, cfg, nowIso);
      if (mcp.refused) reply = `refused: ${mcp.refused}`;
      else {
        s.calls += 1;
        run.push({ call_id: c.id, tool: c.function.name, args, mcp });
      }
    }
    if (reply) {
      s.messages.push({ role: 'tool', tool_call_id: c.id, content: reply });
      s.log.push({ call_id: c.id, tool: c.function.name, args, ok: false, text: reply });
    }
  }
  if (s.end_reason === 'tool call budget' && !run.length) {
    s.final_turn = true;
    s.messages.push({ role: 'user', content: 'The tool budget is used up. Answer now with the JSON, from what you have.' });
  }
  return run.length ? { kind: 'tools', state: s, calls: run } : { kind: 'continue', state: s };
}

function mcpText(body) {
